window.FZ = window.FZ || {};
FZ.NPCS = [
  {
    id: 'roommate', name: '小周', role: '同寝室友', mark: '周', color: '#FFB020', outfit: 'student',
    places: ['dorm', 'library', 'dorm'],
    bio: '嘴上说着随缘，闹钟却比所有人都早。书桌上永远有半杯咖啡。',
    greeting: ['醒了？我替你占了洗漱的位置，没替你复习。今天先攻哪门？', '嘘，我终于离开被窝了。这张桌子今天属于复习小队。', '灯给你留着。但说好了，今晚谁先困，谁就有权先睡。'],
    topics: [
      { id: 'plan', label: '聊聊复习计划', replies: ['先拿一张纸写三门课，不要打开十个软件。你最怕的《{科目}》也从一道会做的题开始。', '把同一门课刷到满分很爽，可另外两门不会自己及格。轮换着来，我监督你。', '今晚不比谁睡得晚。把明天要带的东西装好，剩下的一页错题就够了。'] },
      { id: 'room', label: '最近寝室有什么事？', replies: ['隔壁昨晚在背书，楼上在搬椅子。我们寝室唯一按时睡觉的是那盆绿萝。', '我把外卖盒收了，窗也开了。回去会像一个人能住的房间，别太感动。', '阳台的衣服还没干，热水还剩一壶。再难的期末周，也要有一点正常生活。'] },
      { id: 'support', label: '我有点撑不住了', replies: ['那就先吃早饭。你不是一份待优化的计划，是一个需要吃饭的人。', '书看不进去时，出来走一圈不叫浪费时间。要不我们去中庭看树？', '挂一门课也不是世界末日。你现在先睡，我明天叫你。真的。'] }
    ]
  },
  {
    id: 'senior', name: '林学姐', role: '复习搭子', mark: '林', color: '#B6F03C', outfit: 'student',
    places: ['library', 'classroom', 'library'],
    bio: '带着一叠有折角的旧笔记。擅长把复杂的事拆成今天能做完的一步。',
    greeting: ['早上的脑子最清醒，先留给真正难的东西吧。', '刚下答疑课。你来的正好，有什么卡住的？', '闭馆之前还有一点时间。我们不卷数量，只解决一个问题。'],
    topics: [
      { id: 'method', label: '怎么复习更有效？', replies: ['《{科目}》别只看懂答案。合上书自己讲一遍，讲不顺的地方才是今天的任务。', '把会的、半会的、不会的题分开。优先补半会的，短时间最容易拿回分数。', '睡前只回看白天标过的错处。现在开一个全新章节，通常只会让人更慌。'] },
      { id: 'balance', label: '三门课该怎么分配？', replies: ['学分高、掌握低的课先救。但别让一门课连续几轮都被冷落。', '侧边那三条掌握度比待办清单诚实。先看最危险的那条，再决定这一个时段。', '不要因为一门已经投入很多，就把剩下的时间全砸进去。保住另外两门也是进步。'] },
      { id: 'story', label: '你也经历过这种时候？', replies: ['当然。我第一次期末带了五支笔，忘了带学生证。后来才学会给自己留缓冲。', '我也有过一天只写出两道题的时候。把不会的问明白，比假装努力一整天更有用。', '以前我觉得熄灯像认输。后来发现睡醒还能继续，才是最大的优势。'] }
    ]
  },
  {
    id: 'librarian', name: '陈老师', role: '图书管理员', mark: '陈', color: '#56C8D8', outfit: 'staff',
    places: ['library', 'library', 'library'],
    bio: '记得每一排书的位置，也记得总在同一个座位犯困的学生。',
    greeting: ['早上好。窗边有空位，进去前把手机调成静音。', '人多了，走路放轻一点。需要参考书可以问我。', '夜间自习区还开着。记得看时间，别错过宿舍门禁。'],
    topics: [
      { id: 'seat', label: '有什么自习建议？', replies: ['靠窗适合阅读，里侧更适合做题。先选一种任务，再选座位，不必来回换。', '人来人往会分心，就把桌上的材料减到一份。让眼前只剩下正在做的题。', '台灯照的是书，不是你的睡眠债。读到一句话反复三遍，就该休息了。'] },
      { id: 'books', label: '借书和资料怎么找？', replies: ['先看目录和索引，找与你当前问题相关的那几页。参考书不是越厚越有效。', '复印资料可以去打印店，原书留给下一位同学。借走之前别忘了办手续。', '还书箱整夜可用。书里如果夹着你的便签，取走它，也把今天的收获带走。'] },
      { id: 'campus', label: '这里有什么小故事？', replies: ['最早来开门的人不是我，是每天蹲在台阶上的那只猫。它比考试周还准时。', '以前有人在借书卡背面写鼓励的话。我们把卡留下了，偶尔会给紧张的同学看。', '关灯后书架会安静下来。明天再来，书和座位还在，不用一次读完。'] }
    ]
  },
  {
    id: 'tutor', name: '许助教', role: '课程助教', mark: '许', color: '#9F9AFF', outfit: 'staff',
    places: ['classroom', 'classroom', 'campus'],
    bio: '口袋里装着红笔和粉笔。说得最多的一句话是“你的思路是什么”。',
    greeting: ['来得早，黑板还是干净的。先说说哪里没想通。', '答疑不需要准备一个完美的问题。把你卡住的那一步给我看。', '我也下班了。路上可以聊聊，但今晚不再开新专题。'],
    topics: [
      { id: 'exam', label: '考试时有什么建议？', replies: ['先看全卷，把确定能拿的分拿到。不会的一题，不值得吞掉后面所有题的时间。', '结论之外，把关键步骤写清楚。哪怕没有走到最后，正确的思路也有价值。', '明天先检查姓名和证件，再检查会不会做题。这两件事的顺序不能反过来。'] },
      { id: 'stuck', label: '一道题总是做不出来', replies: ['把题目的已知条件逐条写下来。你以为不会的，可能只是还没有找到起点。', '别把“我不会这一步”扩大成“我什么都不会”。准确的问题才有准确的答案。', '先把卡点圈出来。休息后再看，往往比现在强迫自己盯着更清楚。'] },
      { id: 'office', label: '什么时候能来答疑？', replies: ['白天来教学楼找我。带上你自己的尝试，哪怕只有两行。', '我通常在黑板旁边。人多时先记下问题，也听听别人的问题。', '明天白天我回教学楼。现在先散散步，脑子也需要下课。'] }
    ]
  },
  {
    id: 'cook', name: '刘姨', role: '食堂窗口', mark: '刘', color: '#F49B78', outfit: 'cook',
    places: ['canteen', 'canteen', 'canteen'],
    bio: '勺子一抖不是少给，是又加了一点。听得懂“赶时间”和“还没吃饭”。',
    greeting: ['热粥刚出锅。没吃早饭就去背书，背进去的都是饿字。', '排队别急，热饭都有。今天看起来比昨天精神一点。', '夜宵窗口还留着。吃点热的，别只靠咖啡撑着。'],
    topics: [
      { id: 'food', label: '今天吃什么好？', replies: ['鸡蛋配粥，带个包子。不追求仪式感，先让胃知道今天开始了。', '饭、菜、蛋白质都带一点。别拿一杯奶茶假装自己吃过午饭。', '清淡点，热乎点。吃得舒服，回去才能睡得舒服。'] },
      { id: 'care', label: '最近复习太累了', replies: ['累了不丢人。你们天没亮就跑去图书馆，我都看在眼里。', '坐下来慢慢吃。这二十分钟不必和任何人比赛。', '书本等你一个晚上不会跑。身体这门课，也不能挂。'] },
      { id: 'news', label: '校园最近热闹吗？', replies: ['清早有同学跑步，有同学背书。那只橘猫两边都陪，最后来我这儿等饭。', '打印店今天人多。真要印东西就早点去，别把晚饭也排进队里。', '保安师傅刚巡过去。外面路灯亮着，回寝室走大路。'] }
    ]
  },
  {
    id: 'printer', name: '老唐', role: '打印店店主', mark: '唐', color: '#F27BC1', outfit: 'staff',
    places: ['print', 'print', 'print'],
    bio: '在打印机的轰鸣里工作。见过最多的不是试卷，是凌晨两点的文件名。',
    greeting: ['文件带好了？先看一眼预览，省得打出八十页空白。', '排队的同学先把文件整理好，轮到你就快了。', '灯还亮着，我还在。最后一份资料也别慌着交给机器。'],
    topics: [
      { id: 'print', label: '打印之前要检查什么？', replies: ['页数、单双面、纸张方向。尤其看清是不是把演讲备注一起导出了。', '先转成 PDF 再确认预览。机器不会替你理解“差不多就行”。', '文件名写清楚。别给我三个“最终版”，我也猜不出哪个最最终。'] },
      { id: 'notes', label: '资料是不是越多越好？', replies: ['能读完十页，比背着一百页安心。纸的重量不能换成脑子的容量。', '圈出真正要看的页再印。剩下的钱留着吃饭，我支持。', '今晚还没看完的那一叠，先别再加厚了。整理也是复习。'] },
      { id: 'story', label: '期末周有什么趣事？', replies: ['有人把“不要打印这一页”也打印了。后来那页成了店里的提醒牌。', '大家的文件夹都在进化：最终、最终2、真的最终。每年如此。', '这盏灯陪过很多届同学。你现在觉得过不去的，以后也会变成故事。'] }
    ]
  },
  {
    id: 'guard', name: '王师傅', role: '校园保安', mark: '王', color: '#719BCE', outfit: 'guard',
    places: ['campus', 'print', 'campus'],
    bio: '手电、钥匙和一只保温杯。夜深后，校园里最让人安心的脚步声。',
    greeting: ['早。校园刚醒，路上慢点走。', '我来看看这边排队的情况。别堵着门口，大家都赶时间。', '这么晚了还在外面？走有路灯的这条路，我巡完这圈也回去了。'],
    topics: [
      { id: 'route', label: '想在校园转一转', replies: ['中庭连着几条主路。图书馆在北，食堂在南，宿舍在西，教学楼在东。', '沿着中间的环路走，不容易绕晕。看见粉色招牌就是打印店。', '沿路灯走大路。草地和自行车棚之间有小道，但夜里不必抄近路。'] },
      { id: 'night', label: '夜里校园是什么样？', replies: ['白天你听到人声，夜里会听到风和脚步。同一个校园，换了种说话方式。', '等到天黑，窗里会一盏一盏亮起来。有人学习，有人打电话回家。', '有时候只剩打印机还响。你不是唯一一个在努力的人，也不用成为最后一个。'] },
      { id: 'cat', label: '那只校园猫在哪？', replies: ['喜欢在中庭晒太阳，谁跑得慢它就跟谁。', '可能去食堂了。它的作息比课表稳定，不需要你替它操心。', '找个暖和地方睡去了。你也该学学它，知道什么时候休息。'] }
    ]
  },
  {
    id: 'runner', name: '阿宁', role: '社团同学', mark: '宁', color: '#7DC9A0', outfit: 'runner',
    places: ['campus', 'canteen', 'campus'],
    bio: '把跑步当成脑内缓存清理。总能发现校园角落里不太显眼的变化。',
    greeting: ['刚跑完一小圈。来，深呼吸一下，今天还没开始难呢。', '运动完再吃饭，什么都香。你今天有没有离开过座位？', '晚风挺舒服的。不跑也行，陪我走到下一盏路灯。'],
    topics: [
      { id: 'break', label: '休息会不会浪费时间？', replies: ['你会给手机充电，为什么不肯给自己十分钟？走完一圈再回去。', '休息不是一直刷到更累。喝水、伸展、看看远处，这几件事比较管用。', '现在散步是为了回去能睡着，不是为了再多熬两个小时。说好了。'] },
      { id: 'club', label: '社团最近怎么样？', replies: ['活动先暂停了，群里变成互相叫起床。考完再一起把欠的电影看掉。', '有人在设计考后野餐。光想着那一天，今天就有一点盼头。', '我们约好考完在中庭合影。没人需要拿满分才有资格站进去。'] },
      { id: 'look', label: '校园里有什么值得看？', replies: ['长椅边的花和树影，早上最好看。走快了就会错过。', '去看食堂门口的小黑板。每日菜单最后一行经常藏着一句鼓励。', '抬头看窗灯，再看天上的星星。世界比你的复习清单大一点。'] }
    ]
  },
  {
    id: 'baller', name: '江越', role: '球场同学', mark: '江', color: '#F39A45', outfit: 'runner',
    places: ['court', 'court', 'court'],
    bio: '课本里夹着球赛票根，球包侧袋塞着错题纸。喜欢清早空球场里一下一下的回声。',
    greeting: ['早，球落地的声音是不是传得特别远？我还在热身，今天不急着投远的。', '刚把球捡回来。场边也挺适合透口气，不一定非得上场。', '晚风把球衣吹凉了。我准备收球，今天没投进的留到下次。'],
    topics: [
      { id: 'baller_rhythm', label: '你平时怎么练球？', replies: ['先活动脚踝和肩膀，再慢慢运球。早上手还没醒，球倒是挺有主意，总想往旁边跑。', '我最近只练一个位置的投篮。总换地方像总换复习资料，看着忙，其实没摸清手感。', '最后几个球我会放慢一点，不拿“投进才回去”跟自己较劲。不然球场都安静了，我还在罚自己。'] },
      { id: 'baller_court', label: '球场有什么小故事？', replies: ['以前晨练总碰见一个抱着书背单词的同学。我球一落地，他就念一个，后来嫌我节奏太乱。', '期末周凑不齐整队，大家就各练各的。偶尔帮旁边的人捡个球，点点头，也算打过招呼了。', '有次散场，大家聊了半天明早考什么，才发现不是同一个年级。平时都只记得谁爱从左边突破。'] },
      { id: 'baller_reset', label: '运动时还会想着考试吗？', replies: ['会啊，出门前还在想一道题。但系鞋带、活动肩膀的时候，先顾眼前这件小事就挺好。', '刚才投丢了三个，我差点连明天的考试都一起否定了。后来想想，球没进就是球没进，别把两件事绑一起。', '也不是每次出来都能想通什么。有时只是吹了会儿风，回去愿意洗澡睡觉了，这样就够了。'] }
    ]
  },
  {
    id: 'gardener', name: '叶然', role: '园艺志愿者', mark: '叶', color: '#72B77A', outfit: 'gardener',
    places: ['garden', 'garden', 'garden'],
    bio: '帆布袋里总有一副沾土的手套。认得花园里的小苗，也认得风穿过不同叶片的声音。',
    greeting: ['早上好。叶尖的水珠还没干，沿着小路走就能看见，不用踩进花坛。', '我在树荫里歇一会儿。刚摘下手套，手指还保持着握小铲子的样子。', '天色暗下来，花的颜色淡了，叶子的轮廓倒更清楚。今天的活儿已经收好了。'],
    topics: [
      { id: 'gardener_plants', label: '照顾植物有什么讲究？', replies: ['先看土和叶子的状态，再决定要不要浇水。天天惦记着是好事，天天浇可不一定，植物也怕被照顾得太满。', '中午叶子有点垂，不一定就是缺水。我会先看看它是不是晒着了，不急着拿水壶下结论。', '光线不够就不忙着修剪，明早看清楚再说。有些叶子只是老了，不是整株都出了问题。'] },
      { id: 'gardener_seasons', label: '花园最近有什么变化？', replies: ['我以前只盯着开花的地方，后来发现新叶也有自己的颜色。嫩一点、亮一点，每天变化都很小。', '风一吹，花影会从路的一边挪到另一边。我在这里待久了，偶尔靠影子就知道该回去吃饭了。', '以前记志愿日志，总觉得没有花开就没什么可写。后来连一片落叶都能写两句，花园可没真的停过。'] },
      { id: 'gardener_pause', label: '你怎么在这里慢下来？', replies: ['我会先听一会儿叶子响，不急着给今天列清单。有些声音很轻，要站定才听得到。', '以前除草时也想着作业，越急越容易把小苗认错。现在手上做什么，就先认认真真看着什么。', '收好工具就算今天结束，不等每片叶子都整齐。复习也是吧，总得给一个不那么完美的晚上画个句号。'] }
    ]
  },
  {
    id: 'photographer', name: '沈禾', role: '校园摄影爱好者', mark: '沈', color: '#AF8CDD', outfit: 'photographer',
    places: ['garden', 'court', 'garden'],
    bio: '相机背带磨得发软，手机相册里也存了许多普通的树影。比起摆好的合影，更留意校园自然的样子。',
    greeting: ['早。花园这会儿的光很柔，我刚才看一片叶子的影子看了好久。', '我来球场看看光线。人动起来，影子也跟着跑，和早上的花园完全不一样。', '又绕回花园了。天暗了我就把相机收起来，有些景色只用眼睛记也挺好。'],
    topics: [
      { id: 'photographer_light', label: '什么光线适合拍照？', replies: ['早上的侧光能把叶片边缘照亮。不必对着太阳找，我常常转个身，才发现好看的光在背后。', '球场的光直一点，影子也利落。我会先看亮处和暗处怎么分开，不急着把每个地方都拍清楚。', '天暗以后，亮的地方很容易抢走注意力。与其追着灯拍，不如看看灯旁边还留下了什么轮廓。'] },
      { id: 'photographer_frame', label: '普通风景怎么取景？', replies: ['先选一样你真正在看的东西，叶子也行，路上的影子也行。画面里少放一点，反而更像你当时的心情。', '在球场我会站在边上，不挡别人的路。想拍到能认出脸的人，先问对方愿不愿意，比构图重要。', '不用为了找角度走进花坛，也不用摸黑往偏处钻。站在小路上看见的风景，已经足够组成一个晚上。'] },
      { id: 'photographer_memory', label: '你最喜欢哪张校园照片？', replies: ['有张是花园里一片卷起来的叶子，没什么特别的。可每次看见，我都记得那天早饭吃得很香。', '一张散场后的球场照片，没人，只有留在地上的长影子。朋友说太空了，我倒觉得像终于下课。', '以前我总删掉拍虚的照片。后来留下一张走路时晃到的树影，反而能想起那天风有多大。'] }
    ]
  },
  {
    id: 'barista', name: '苏晚', role: '咖啡角店员', mark: '苏', color: '#BE8C65', outfit: 'barista',
    places: ['cafe', 'cafe', 'cafe'],
    bio: '围裙口袋里别着一支短铅笔。习惯擦净杯沿，也习惯在咖啡机安静下来的片刻听听窗外。',
    greeting: ['早上好。刚才磨豆的声音有点响，现在安静了，空气里还留着一点烤坚果似的香气。', '午后好。我刚擦完桌子，窗外人来人往，坐在这里看着倒不觉得急。', '晚上好。忙过一阵，杯子也都摆整齐了。你要是困了，就别跟睡意较劲。'],
    topics: [
      { id: 'barista_aroma', label: '咖啡为什么有不同的香气？', replies: ['豆子和烘焙程度不同，闻起来就不一样。有的像坚果，有的有点果香，不是每一种都得闻出标准答案。', '热的时候香气明显，稍微凉一点又会有变化。我刚入行时只会说“挺香”，也是慢慢才分出不同的。', '闻到咖啡香，不代表现在就需要喝咖啡。我忙完闻着满屋子的味道，最想喝的常常只是温水。'] },
      { id: 'barista_corner', label: '咖啡角有什么日常故事？', replies: ['常有同学抱着书走过窗边，走到一半又折回去，大概忘了东西。我也常找铅笔，最后发现它就在口袋里。', '有回两位同学在这儿互相讲题，越讲声音越小，最后一起笑起来。听说是终于发现两个人都看错了题号。', '傍晚窗上会映出屋里的灯，外面的树影和杯子叠在一起。我擦窗时偶尔停一下，像看见校园多了一层。'] },
      { id: 'barista_rest', label: '期末周要靠咖啡提神吗？', replies: ['别把咖啡当早饭，也不用因为别人都喝就跟着喝。昨晚睡得怎么样，比今天杯子有多大更值得问。', '我见过有人越困越着急，一边翻书一边忘了自己还没吃午饭。先照顾好吃饭和休息，咖啡替不了这些。', '如果已经困了，就顺着身体的意思休息吧。我自己晚上也会避开咖啡，明天还有明天的精神要用。'] }
    ]
  }
];

